INSERT INTO landscape_hot_topic (id, title, category, data) VALUES
('ht-1', '极光摄影', '星空夜景', '{"title":"极光摄影","category":"星空夜景","image":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/1.webp","description":"探索世界各地的极光现象，掌握拍摄极光的最佳时机和技巧","views":"12.5k","likes":"1.8k","favorites":"567","comments":"234","date":"2024-02-15","bestSeason":"冬季","locations":["冰岛·雷克雅未克","挪威·特罗姆瑟","芬兰·罗瓦涅米","加拿大·黄刀镇"],"tips":["选择冬季晴朗的夜晚，避开满月","使用三脚架和快门线，长曝光拍摄","设置高ISO和大光圈，保证足够的进光量","寻找有前景的构图，增加画面层次感"],"navigation":{"dimension":"theme","category":"sky","subCategory":"aurora"}}'),
('ht-2', '山岳风光', '自然风光', '{"title":"山岳风光","category":"自然风光","image":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/2.webp","description":"征服高山峻岭，捕捉壮丽的山岳风光和云海奇观","views":"9.8k","likes":"1.2k","favorites":"389","comments":"187","date":"2024-01-20","bestSeason":"春秋","locations":["瑞士·阿尔卑斯山脉","中国·黄山","美国·落基山脉","新西兰·南阿尔卑斯山脉"],"tips":["选择日出或日落时分，光线最柔和","提前了解天气状况，云海出现的概率","携带广角镜头，捕捉广阔的山景","注意安全，选择安全的拍摄位置"],"navigation":{"dimension":"theme","category":"nature","subCategory":"mountain"}}'),
('ht-3', '城市天际线', '城市建筑', '{"title":"城市天际线","category":"城市建筑","image":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/4.webp","description":"探索全球著名城市的天际线，捕捉现代都市的魅力","views":"15.2k","likes":"2.1k","favorites":"678","comments":"312","date":"2024-02-05","bestSeason":"四季","locations":["美国·纽约","中国·上海","阿联酋·迪拜","新加坡"],"tips":["选择高处拍摄点，如观景台或摩天大楼","黄金时刻拍摄，城市灯光和自然光平衡","使用三脚架，保证画面清晰","尝试不同角度，寻找独特的构图"],"navigation":{"dimension":"theme","category":"urban","subCategory":"skyline"}}'),
('ht-4', '海滩日落', '海边风光', '{"title":"海滩日落","category":"海边风光","image":"https://mouthhard-website.oss-cn-hangzhou.aliyuncs.com/landscape/5.webp","description":"追逐最美的海滩日落，记录夕阳西下的浪漫时刻","views":"10.7k","likes":"1.5k","favorites":"423","comments":"203","date":"2024-01-15","bestSeason":"夏季","locations":["马尔代夫","巴厘岛·库塔海滩","夏威夷·威基基海滩","澳大利亚·黄金海岸"],"tips":["提前到达拍摄地点，占据最佳位置","使用渐变滤镜，平衡天空和地面曝光","捕捉海浪和沙滩的纹理，增加画面细节","尝试不同的构图，如三分法或引导线"],"navigation":{"dimension":"theme","category":"water","subCategory":"beach"}}');
